from collections import defaultdict
def frame_demo(name,color):
    I=np.array(G[name+' input']); O=np.array(G[name+' output'])
    lab,n=label(I==0); H,W=I.shape
    P=[r[:] for r in I.tolist()]
    for k in range(1,n+1):
        ys,xs=np.where(lab==k)
        y0,y1,x0,x1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
        if len(ys)<2 or y1-y0<2 or x1-x0<2: continue
        R=[(y0-1,j) for j in range(max(0,x0-1),min(W,x1+2))]+[(y1+1,j) for j in range(max(0,x0-1),min(W,x1+2))]
        R+=[(i,max(0,x0-1)) for i in range(max(0,y0-1),min(H,y1+2))]+[(i,min(W-1,x1+1)) for i in range(max(0,y0-1),min(H,y1+2))]
        for y,x in R: P[y][x]=color
    mism=[(y,x,int(P[y][x]),int(O[y,x])) for y in range(H) for x in range(W) if P[y][x]!=int(O[y,x])]
    return P,mism
